CREATE TABLE mcp_server_templates(id TEXT NOT NULL PRIMARY KEY, name TEXT NOT NULL UNIQUE, server_url TEXT NOT NULL CHECK(length(server_url) BETWEEN 1 AND 2048), org_id TEXT REFERENCES organizations(id), provider_flow TEXT NOT NULL CHECK(provider_flow IN ('authorization_code','client_credentials','none')), discovery_metadata TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX mcp_server_templates_org ON mcp_server_templates(org_id);
CREATE TABLE mcp_connections(id TEXT NOT NULL PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), server_id TEXT NOT NULL REFERENCES mcp_server_templates(id) ON DELETE CASCADE, server_url_override TEXT CHECK(server_url_override IS NULL OR length(server_url_override) BETWEEN 1 AND 2048), token_path TEXT CHECK(token_path IS NULL OR length(token_path) BETWEEN 1 AND 512), client_id TEXT CHECK(client_id IS NULL OR length(client_id) BETWEEN 1 AND 256), available_in_chat INTEGER NOT NULL DEFAULT 0 CHECK(available_in_chat IN (0,1)), available_to_autonomous INTEGER NOT NULL DEFAULT 0 CHECK(available_to_autonomous IN (0,1)), enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(server_id, org_id));
CREATE INDEX mcp_connections_org ON mcp_connections(org_id);
CREATE TABLE mcp_tool_catalog(connection_id TEXT NOT NULL REFERENCES mcp_connections(id) ON DELETE CASCADE, tool_name TEXT NOT NULL CHECK(length(tool_name) BETWEEN 1 AND 128), description TEXT CHECK(description IS NULL OR length(description) BETWEEN 1 AND 1024), schema_json TEXT NOT NULL CHECK(length(schema_json) BETWEEN 1 AND 16384), enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), auto_disabled_reason TEXT, synced_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(connection_id, tool_name));
CREATE TABLE mcp_connection_secrets(connection_id TEXT NOT NULL REFERENCES mcp_connections(id) ON DELETE CASCADE, org_id TEXT NOT NULL REFERENCES organizations(id), field TEXT NOT NULL CHECK(length(field) BETWEEN 1 AND 64), ciphertext TEXT NOT NULL CHECK(length(ciphertext) BETWEEN 1 AND 8192), nonce TEXT NOT NULL CHECK(length(nonce) BETWEEN 1 AND 128), wrapped_dek TEXT NOT NULL CHECK(length(wrapped_dek) BETWEEN 1 AND 2048), key_version INTEGER NOT NULL CHECK(key_version >= 1), algorithm TEXT NOT NULL CHECK(algorithm IN ('AES-GCM-256')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(connection_id, field));
CREATE INDEX mcp_connection_secrets_org ON mcp_connection_secrets(org_id);
CREATE TABLE mcp_service_tokens(connection_id TEXT NOT NULL PRIMARY KEY REFERENCES mcp_connections(id) ON DELETE CASCADE, org_id TEXT NOT NULL REFERENCES organizations(id), access_ciphertext TEXT NOT NULL CHECK(length(access_ciphertext) BETWEEN 1 AND 8192), access_nonce TEXT NOT NULL CHECK(length(access_nonce) BETWEEN 1 AND 128), access_wrapped_dek TEXT NOT NULL CHECK(length(access_wrapped_dek) BETWEEN 1 AND 2048), refresh_ciphertext TEXT CHECK(refresh_ciphertext IS NULL OR length(refresh_ciphertext) BETWEEN 1 AND 8192), refresh_nonce TEXT CHECK(refresh_nonce IS NULL OR length(refresh_nonce) BETWEEN 1 AND 128), refresh_wrapped_dek TEXT CHECK(refresh_wrapped_dek IS NULL OR length(refresh_wrapped_dek) BETWEEN 1 AND 2048), key_version INTEGER NOT NULL CHECK(key_version >= 1), algorithm TEXT NOT NULL CHECK(algorithm IN ('AES-GCM-256')), generation INTEGER NOT NULL CHECK(generation >= 1), scope TEXT NOT NULL DEFAULT '', expires_at_ms INTEGER, status TEXT NOT NULL CHECK(status IN ('healthy','failed','revoked')), consecutive_failures INTEGER NOT NULL DEFAULT 0 CHECK(consecutive_failures >= 0), last_failure_code TEXT, last_success_at TEXT, checked_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX mcp_service_tokens_org ON mcp_service_tokens(org_id);
CREATE TABLE mcp_user_consents(connection_id TEXT NOT NULL REFERENCES mcp_connections(id) ON DELETE CASCADE, user_id TEXT NOT NULL CHECK(length(user_id) BETWEEN 1 AND 320), org_id TEXT NOT NULL REFERENCES organizations(id), scope TEXT NOT NULL DEFAULT '', consent_granted_at TEXT NOT NULL, consent_expires_at TEXT, access_ciphertext TEXT NOT NULL CHECK(length(access_ciphertext) BETWEEN 1 AND 8192), access_nonce TEXT NOT NULL CHECK(length(access_nonce) BETWEEN 1 AND 128), access_wrapped_dek TEXT NOT NULL CHECK(length(access_wrapped_dek) BETWEEN 1 AND 2048), refresh_ciphertext TEXT CHECK(refresh_ciphertext IS NULL OR length(refresh_ciphertext) BETWEEN 1 AND 8192), refresh_nonce TEXT CHECK(refresh_nonce IS NULL OR length(refresh_nonce) BETWEEN 1 AND 128), refresh_wrapped_dek TEXT CHECK(refresh_wrapped_dek IS NULL OR length(refresh_wrapped_dek) BETWEEN 1 AND 2048), key_version INTEGER NOT NULL CHECK(key_version >= 1), algorithm TEXT NOT NULL CHECK(algorithm IN ('AES-GCM-256')), generation INTEGER NOT NULL CHECK(generation >= 1), expires_at_ms INTEGER, status TEXT NOT NULL CHECK(status IN ('healthy','failed','revoked')), consecutive_failures INTEGER NOT NULL DEFAULT 0 CHECK(consecutive_failures >= 0), last_failure_code TEXT, last_success_at TEXT, checked_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(connection_id, user_id));
CREATE INDEX mcp_user_consents_org ON mcp_user_consents(org_id);
